format:
/* ===== DASHBOARD SOLAR MINIMALISTA ===== */

html,
body,
#app,
.v-application,
.v-application__wrap,
.v-main,
.v-main__wrap,
.nrdb-ui-dashboard {
    background: #f4f7f9 !important;
    font-family: Arial, Helvetica, sans-serif !important;
}

/* Barra superior */
.v-toolbar,
header,
.v-app-bar {
    background: #ffffff !important;
    color: #1f2933 !important;
    box-shadow: 0 2px 10px rgba(0, 0, 0, .08) !important;
    border-bottom: 1px solid #e5e7eb !important;
}

.v-toolbar-title,
.v-app-bar-title {
    font-weight: 800 !important;
    letter-spacing: .2px !important;
}

/* Contenedores principales */
.v-card,
.nrdb-ui-group {
    background: #ffffff !important;
    border-radius: 18px !important;
    border: 1px solid #e5e7eb !important;
    box-shadow: 0 6px 18px rgba(31, 41, 51, .08) !important;
    overflow: hidden !important;
    margin-bottom: 18px !important;
}

/* Títulos de grupos */
.v-card-title,
.nrdb-ui-group-title {
    background: #ffffff !important;
    color: #1f2933 !important;
    font-size: 24px !important;
    font-weight: 800 !important;
    padding: 18px 22px !important;
    border-bottom: 1px solid #edf0f2 !important;
}

/* Botones */
.v-btn,
button {
    border-radius: 12px !important;
    font-weight: 700 !important;
    text-transform: none !important;
    box-shadow: none !important;
    transition: all .2s ease-in-out !important;
}

.v-btn:hover,
button:hover {
    transform: translateY(-1px) !important;
    box-shadow: 0 6px 14px rgba(0, 0, 0, .12) !important;
}

/* Botones amarillos más suaves */
.v-btn.bg-primary,
button {
    background: #fbbf24 !important;
    color: #111827 !important;
}

/* Tarjetas internas de gauges */
.nrdb-ui-gauge {
    background: #fafafa !important;
    border-radius: 16px !important;
    border: 1px solid #eeeeee !important;
    padding: 10px !important;
}

/* Títulos de widgets */
.nrdb-ui-gauge label,
.nrdb-ui-gauge .label {
    color: #111827 !important;
    font-weight: 800 !important;
}

/* Textos */
.v-card-text,
.nrdb-ui-text {
    color: #374151 !important;
    font-size: 16px !important;
}

/* Banner principal que ya tienes */
.solar-banner,
.banner-solar,
.panel-header {
    background: linear-gradient(135deg, #ffffff, #f9fafb) !important;
    color: #1f2933 !important;
    border-radius: 16px !important;
    border: 1px solid #e5e7eb !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, .06) !important;
}

.solar-banner h1,
.banner-solar h1,
.panel-header h1,
.panel-header h2 {
    color: #111827 !important;
    font-weight: 800 !important;
}

.solar-banner p,
.banner-solar p,
.panel-header p {
    color: #6b7280 !important;
}

/* Tarjeta de alarmas */
.alarma-card {
    background: #ffffff !important;
    border: 1px solid #e5e7eb !important;
    border-left: 5px solid #22c55e !important;
    border-radius: 16px !important;
    padding: 16px !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, .07) !important;
}

.alarma-card h3,
.alarma-card h2 {
    color: #111827 !important;
    font-weight: 800 !important;
    margin-bottom: 12px !important;
}

/* LEDs */
.led {
    width: 22px !important;
    height: 22px !important;
    border-radius: 50% !important;
    display: inline-block !important;
    margin-right: 12px !important;
    border: 2px solid #ffffff !important;
}

.led-verde {
    background: #22c55e !important;
    box-shadow: 0 0 12px rgba(34, 197, 94, .65) !important;
}

.led-rojo {
    background: #ef4444 !important;
    box-shadow: 0 0 12px rgba(239, 68, 68, .7) !important;
    animation: parpadeo-suave 1.2s infinite !important;
}

@keyframes parpadeo-suave {
    0% {
        opacity: 1;
    }

    50% {
        opacity: .45;
    }

    100% {
        opacity: 1;
    }
}

/* Gráfica */
.nrdb-ui-chart,
canvas {
    background: #ffffff !important;
    border-radius: 16px !important;
}

/* Quita bordes visuales exagerados */
* {
    scrollbar-color: #cbd5e1 #f1f5f9;
}
